import { useLayoutEffect } from "react";

interface HeadStyleProps {
  id: string;
  css: string;
}

const refCounts = new Map<string, number>();

/**
 * Injects a <style> element into document.head with the given CSS.
 * Uses useLayoutEffect to apply styles before paint, avoiding flash of unstyled content.
 * Multiple instances with the same id share a single element; the element is only
 * removed when all instances have unmounted.
 */
export const HeadStyle = ({ id, css }: HeadStyleProps) => {
  // Effect 1: Element lifecycle management (ref counting)
  // Only runs on mount, unmount, or when `id` changes
  useLayoutEffect(() => {
    let el = document.getElementById(id) as HTMLStyleElement | null;

    if (!el) {
      el = document.createElement("style");
      el.id = id;
      document.head.appendChild(el);
    }

    refCounts.set(id, (refCounts.get(id) ?? 0) + 1);

    return () => {
      const count = (refCounts.get(id) ?? 0) - 1;
      if (count <= 0) {
        refCounts.delete(id);
        document.getElementById(id)?.remove();
      } else {
        refCounts.set(id, count);
      }
    };
  }, [id]);

  // Effect 2: Content updates
  // Runs when `css` changes without affecting ref counting
  useLayoutEffect(() => {
    const el = document.getElementById(id) as HTMLStyleElement | null;
    if (el) {
      el.textContent = css;
    }
  }, [id, css]);

  return null;
};

import { type ComponentProps, Fragment } from "react";

import { cx } from "@hashintel/ds-helpers/css";

import { useLadleIsPreview } from "../hooks/use-ladle-control";

export const PreviewFrame = ({
  children,
  className,
  ...divProps
}: ComponentProps<"div">) => {
  const isPreview = useLadleIsPreview();
  return isPreview ? (
    <div className={cx("p-6", className)} {...divProps}>
      {children}
    </div>
  ) : (
    <Fragment>{children}</Fragment>
  );
};

import React, { type CSSProperties } from "react";

import { cx } from "@hashintel/ds-helpers/css";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type CellProps<C extends Record<string, any>> = Partial<
  C & {
    cellClassName?: string;
  }
>;

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const VariantGrid = <C extends Record<string, any>>({
  children,
  cols,
  rows,
  cellClassName: gridCellClassName,
  gridGap = 20,
}: Readonly<{
  cols?: CellProps<C>[];
  rows?: CellProps<C>[];
  gridGap?: number;
  cellClassName?: string;
  children: (props: C) => React.ReactElement<C>;
}>) => {
  cols ??= [{}];
  rows ??= [{}];
  return (
    <div
      className="grid grid-flow-row auto-rows-max grid-cols-[--num-cols] items-start justify-items-start gap-[--grid-gap]"
      style={
        {
          "--num-cols": `repeat(${cols.length}, minmax(max-content, 1fr))`,
          "--grid-gap": `${gridGap}px`,
        } as CSSProperties
      }
    >
      {rows.map(({ cellClassName: rowCellClassName, ...r }, i) =>
        cols.map(({ cellClassName: colCellClassName, ...c }, j) => {
          return (
            <div
              key={`row-${i}-col-${j}`}
              className={cx(
                gridCellClassName,
                rowCellClassName,
                colCellClassName,
              )}
            >
              {children({ ...c, ...r } as C)}
            </div>
          );
        }),
      )}
    </div>
  );
};

export function variantMatrix<T extends object>({
  cols,
  rows,
}: Readonly<{
  cols?: Partial<T>[];
  rows?: Partial<T>[];
}>) {
  cols ??= [{}];
  rows ??= [{}];
  return rows.flatMap((r) => cols.map((c) => ({ ...c, ...r }) as T));
}

import { ThemeState, type GlobalProvider } from "@ladle/react";
import { useLayoutEffect } from "react";
import "@fontsource-variable/geist-mono";
import "@fontsource-variable/inter";
import "@fontsource-variable/inter-tight";

import "./index.css";

/**
 * Global provider for Ladle stories.
 * Applies theme class to root element and imports Panda CSS styles.
 */
export const Provider: GlobalProvider = ({
  children,
  globalState: { theme },
}) => {
  useLayoutEffect(() => {
    const root = document.documentElement;

    // Remove existing theme classes
    root.classList.remove("light", "dark");

    // Apply theme class based on Ladle's theme state
    if (theme === ThemeState.Dark) {
      root.classList.add("dark");
    } else if (theme === ThemeState.Light) {
      root.classList.add("light");
    }
    // ThemeState.Auto will use system preference via CSS media queries
  }, [theme]);

  return children;
};

import { ActionType, ModeState, useLadleContext } from "@ladle/react";
import { useIsFirstRender } from "@mantine/hooks";
import { useCallback, useLayoutEffect, useRef } from "react";

const isLazyInitializer = <T>(value: T | (() => T)): value is () => T =>
  typeof value === "function";

const isUpdater = <T>(
  value: T | ((prev: T | undefined) => T) | undefined,
): value is (prev: T | undefined) => T => typeof value === "function";

export function useLadleControl<T>(
  paramName: string,
  initialValue?: T | (() => T),
) {
  const {
    globalState: { control: state },
    dispatch,
  } = useLadleContext();

  // NOTE: not sure if this is needed; only if the init value is somehow dynamic
  const isUnset = useRef(!(paramName in state));
  if (isUnset.current) {
    isUnset.current = false;
    if (initialValue != null) {
      dispatch({
        type: ActionType.UpdateControl,
        value: {
          ...state,
          [paramName]: {
            ...state[paramName],
            value: isLazyInitializer(initialValue)
              ? initialValue()
              : initialValue,
          },
        },
      });
    }
  }

  return useCallback(
    (value?: T | ((prev: T | undefined) => T)) => {
      dispatch({
        type: ActionType.UpdateControl,
        value: {
          ...state,
          [paramName]: {
            ...state[paramName],
            value: isUpdater(value)
              ? value(state[paramName]?.value as T | undefined)
              : (value ?? ("transparent" as T)),
          },
        },
      });
    },
    [dispatch, paramName, state],
  );
}

/**
 * Hook to detect if Ladle is currently in fullscreen (preview) mode.
 *
 * @returns boolean - true if in fullscreen mode, false otherwise
 */
export function useLadleIsPreview(): boolean {
  const { globalState } = useLadleContext();
  return globalState.mode === ModeState.Preview;
}

/**
 * Hook to programmatically set the background color of the Ladle story canvas.
 *
 * @param initialColor - Initial background color (optional)
 * @returns A function to set the background color
 */
export function useLadleBackground(initialColor?: string & {}) {
  const setLadleBackground = useLadleControl("background", initialColor);
  const isFirstRender = useIsFirstRender();
  useLayoutEffect(() => {
    if (initialColor && isFirstRender) {
      setLadleBackground(initialColor);
    }
  }, [initialColor, setLadleBackground, isFirstRender]);

  return setLadleBackground;
}

@layer reset, base, tokens, recipes, utilities;

/* panda's preflight (reset) styles, since we set preflight:false */
@layer reset {
  html,
  :host {
    --font-fallback:
      ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
      Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
      "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol",
      "Noto Color Emoji";
    line-height: 1.5;
    -webkit-text-size-adjust: 100%;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    -moz-tab-size: 4;
    tab-size: 4;
    font-family: var(--global-font-body, var(--font-fallback));
    -webkit-tap-highlight-color: transparent;
  }

  *,
  ::before,
  ::after,
  ::backdrop,
  ::file-selector-button {
    margin: 0px;
    padding: 0px;
    border-width: 0px;
    border-style: solid;
    border-color: var(--global-color-border, currentcolor);
    box-sizing: border-box;
  }

  hr {
    color: inherit;
    height: 0px;
    border-top-width: 1px;
  }

  body {
    line-height: inherit;
    height: 100%;
  }

  img {
    border-style: none;
  }

  img,
  svg,
  video,
  canvas,
  audio,
  iframe,
  embed,
  object {
    display: block;
    vertical-align: middle;
  }

  img,
  video {
    max-width: 100%;
    height: auto;
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    text-wrap: balance;
    font-size: inherit;
    font-weight: inherit;
  }

  p,
  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    overflow-wrap: break-word;
  }

  ol,
  ul,
  menu {
    list-style: none;
  }

  button,
  input:where([type="button"], [type="reset"], [type="submit"]),
  ::file-selector-button {
    appearance: button;
    -webkit-appearance: button;
  }

  button,
  input,
  optgroup,
  select,
  textarea,
  ::file-selector-button {
    font: inherit;
    background: transparent;
    font-feature-settings: inherit;
    font-variation-settings: inherit;
    letter-spacing: inherit;
    color: inherit;
  }

  ::placeholder {
    --placeholder-fallback: rgba(0, 0, 0, 0.5);
    opacity: 1;
    color: var(--global-color-placeholder, var(--placeholder-fallback));
  }

  @supports (not (-webkit-appearance: -apple-pay-button)) or
    (contain-intrinsic-size: 1px) {
    ::placeholder {
      --placeholder-fallback: color-mix(
        in oklab,
        currentcolor 50%,
        transparent
      );
    }
  }

  ::selection {
    background-color: var(--global-color-selection, rgba(0, 115, 255, 0.3));
  }

  textarea {
    resize: vertical;
  }

  table {
    border-color: inherit;
    text-indent: 0px;
    border-collapse: collapse;
  }

  summary {
    display: list-item;
  }

  small {
    font-size: 80%;
  }

  sub,
  sup {
    font-size: 75%;
    line-height: 0;
    position: relative;
    vertical-align: baseline;
  }

  sub {
    bottom: -0.25em;
  }

  sup {
    top: -0.5em;
  }

  dialog {
    padding: 0px;
  }

  a {
    text-decoration: inherit;
    color: inherit;
  }

  abbr:where([title]) {
    text-decoration: underline dotted;
  }

  b,
  strong {
    font-weight: bolder;
  }

  code,
  kbd,
  samp,
  pre {
    --font-mono-fallback:
      ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
      "Courier New";
    font-family: var(--global-font-mono, var(--font-mono-fallback));
    font-size: 1em;
    font-feature-settings: normal;
    font-variation-settings: normal;
  }

  progress {
    vertical-align: baseline;
  }

  ::-webkit-search-decoration,
  ::-webkit-search-cancel-button {
    -webkit-appearance: none;
  }

  ::-webkit-inner-spin-button,
  ::-webkit-outer-spin-button {
    height: auto;
  }

  :-moz-ui-invalid {
    box-shadow: none;
  }

  :-moz-focusring {
    outline: auto;
  }

  [hidden]:where(:not([hidden="until-found"])) {
    display: none !important;
  }
}

:root {
  /* fonts - Fontsource variable fonts */
  --font-inter: "Inter Variable", "Inter", ui-sans-serif, system-ui, sans-serif;
  --font-inter-tight:
    "Inter Tight Variable", "Inter Tight", ui-sans-serif, system-ui, sans-serif;
  --font-geist-mono:
    "Geist Mono Variable", "Geist Mono", ui-monospace, SFMono-Regular, monospace;
  --global-font-body: var(--font-inter);
  --global-font-mono: var(--font-geist-mono);

  /* colors - using radix-based semantic tokens */
  --ladle-bg-color-primary: var(--colors-neutral-s00) !important;
  --ladle-bg-color-secondary: var(--colors-neutral-s20) !important;
  --ladle-color-primary: var(--colors-neutral-s120) !important;
  --ladle-color-secondary: var(--colors-neutral-s110) !important;
  --ladle-color-hover: var(--colors-neutral-s90) !important;
  --ladle-color-accent: var(--colors-blue-s90);
  --ladle-blueprint: var(--colors-blue-s60);

  /* dimensions */
  --ladle-ring-size: 64px;
  --ladle-ring-thickness: 6px;
  --ladle-mode-overflow: hidden;
  --ladle-mode-height: 100vh;
  --ladle-main-padding: 1.5em;
  --ladle-main-padding-mobile: 0.5em;
  --reach-dialog: 1;
}

.ladle-main {
  color: var(--colors-fg-heading);
  background-color: var(--colors-neutral-s00);
}

/* Light mode (default) */
:root,
.light,
[data-theme="light"] {
  color-scheme: light;
}

/* Dark mode */
.dark,
[data-theme="dark"] {
  color-scheme: dark;
}

