    centerButton: {
      display: "inline-flex",
      alignItems: "center",
      alignSelf: "stretch",
      minWidth: "0",
      position: "relative",
      cursor: "pointer",
      appearance: "none",
      border: "none",
      background: "[transparent]",
      color: "[inherit]",
      font: "inherit",
      outline: "none",
      paddingInline: "var(--chip-padding-x)",
