// In a real application, the contexts, field components, and `useAppForm`
// would live in their own module (eg. `app/form.tsx`) and be imported by
// every form in the app — so all forms share styling, validation display,
// and submit behaviour for free.

const { fieldContext, formContext, useFieldContext, useFormContext } =
  createFormHookContexts();

const TextField = ({
  label,
  description,
  size,
  required,
}: {
  label: string;
  description?: string;
  size?: FormInputSize;
  required?: boolean;
}) => {
  const field = useFieldContext<string>();
  return (
    <Form.Field
      as="label"
      label={label}
      description={description}
      size={size}
      required={required}
      errors={field.state.meta.errors}
    >
      <TextInput
        name={field.name}
        value={field.state.value}
        onChange={(value) => field.handleChange(value)}
        onBlur={field.handleBlur}
        size={size}
        invalid={field.state.meta.errors.length > 0}
      />
    </Form.Field>
  );
};

const IntegerField = ({
  label,
  description,
  size,
  required,
  min,
  max,
}: {
  label: string;
  description?: string;
  size?: FormInputSize;
  required?: boolean;
  min?: number;
  max?: number;
}) => {
  const field = useFieldContext<number>();
  return (
    <Form.Field
      as="label"
      label={label}
      description={description}
      size={size}
      required={required}
      errors={field.state.meta.errors}
    >
      <NumberInput
        name={field.name}
        value={field.state.value}
        min={min}
        max={max}
        onChange={(value) => field.handleChange(value ?? 0)}
        onBlur={field.handleBlur}
        size={size}
        invalid={field.state.meta.errors.length > 0}
      />
    </Form.Field>
  );
};

const CheckboxGroupField = ({
  label,
  description,
  size,
  required,
  items,
}: {
  label: string;
  description?: string;
  size?: FormInputSize;
  required?: boolean;
  items: React.ComponentProps<typeof CheckboxGroup>["items"];
}) => {
  const field = useFieldContext<string[]>();
  return (
    <Form.Field
      as="legend"
      label={label}
      description={description}
      size={size}
      required={required}
      errors={field.state.meta.errors}
    >
      <CheckboxGroup
        name={field.name}
        items={items}
        value={field.state.value}
        onChange={(value) => field.handleChange(value)}
        onBlur={field.handleBlur}
        size={size}
        invalid={field.state.meta.errors.length > 0}
      />
    </Form.Field>
  );
};

const RadioGroupField = ({
  label,
  description,
  size,
  required,
  items,
}: {
  label: string;
  description?: string;
  size?: FormInputSize;
  required?: boolean;
  items: React.ComponentProps<typeof RadioGroup>["items"];
}) => {
  const field = useFieldContext<string>();
  return (
    <Form.Field
      as="legend"
      label={label}
      description={description}
      size={size}
      required={required}
      errors={field.state.meta.errors}
    >
      <RadioGroup
        name={field.name}
        items={items}
        value={field.state.value}
        onChange={(value) => field.handleChange(value)}
        onBlur={field.handleBlur}
        size={size}
        invalid={field.state.meta.errors.length > 0}
      />
    </Form.Field>
  );
};

const SubmitButton = ({
  children,
  size,
}: {
  children: string;
  size?: FormInputSize;
}) => {
  const form = useFormContext();
  return (
    <form.Subscribe
      selector={(state) => ({
        canSubmit: state.canSubmit,
        isSubmitting: state.isSubmitting,
      })}
    >
      {({ canSubmit, isSubmitting }) => (
        <div className={submitRowStyle}>
          <Button
            type="submit"
            variant="solid"
            tone="brand"
            size={size}
            disabled={!canSubmit}
            loading={isSubmitting}
          >
            {children}
          </Button>
        </div>
      )}
    </form.Subscribe>
  );
};

const { useAppForm } = createFormHook({
  fieldComponents: {
    TextField,
    IntegerField,
    CheckboxGroupField,
    RadioGroupField,
  },
  formComponents: { SubmitButton },
  fieldContext,
  formContext,
});

export const WithTanstackForm: Story<FormFieldArgs> = (args) => {
  const form = useAppForm({
    defaultValues: {
      fullName: "",
      email: "",
      username: "",
      age: 18,
      interests: [] as string[],
      contactMethod: "",
    },
    onSubmit: ({ value }) => {
      // eslint-disable-next-line no-alert
      window.alert(`Submitted:\n${JSON.stringify(value, null, 2)}`);
    },
  });

  return (
    <form
      className={formStyle}
      onSubmit={(event) => {
        event.preventDefault();
        event.stopPropagation();
        void form.handleSubmit();
      }}
    >
      <form.AppField
        name="fullName"
        validators={{
          onChange: ({ value }) =>
            value.trim().length === 0 ? "Full name is required" : undefined,
        }}
      >
        {(field) => (
          <field.TextField label="Full name" size={args.size} required />
        )}
      </form.AppField>

      <form.AppField
        name="email"
        validators={{
          onChange: ({ value }) => {
            if (value.trim().length === 0) {
              return "Email is required";
            }
            if (!/^\S+@\S+\.\S+$/.test(value)) {
              return "Enter a valid email address";
            }
            return undefined;
          },
        }}
      >
        {(field) => (
          <field.TextField
            label="Email"
            description="We'll never share your email"
            size={args.size}
            required
          />
        )}
      </form.AppField>

      <form.AppField
        name="username"
        validators={{
          onChange: ({ value }) => {
            if (value.trim().length === 0) {
              return "Username is required";
            }
            if (!/^[a-z0-9_]+$/.test(value)) {
              return "Lowercase letters, digits, and underscores only";
            }
            return undefined;
          },
        }}
      >
        {(field) => (
          <field.TextField
            label="Username"
            description="Lowercase letters, digits, and underscores"
            size={args.size}
            required
          />
        )}
      </form.AppField>

      <form.AppField
        name="age"
        validators={{
          onChange: ({ value }) => {
            if (value < 18) {
              return "Must be 18 or older";
            }
            if (value > 120) {
              return "Must be 120 or younger";
            }
            return undefined;
          },
        }}
      >
        {(field) => (
          <field.IntegerField
            label="Age"
            size={args.size}
            min={0}
            max={120}
            required
          />
        )}
      </form.AppField>

      <form.AppField
        name="interests"
        validators={{
          onChange: ({ value }) =>
            value.length === 0 ? "Select at least one interest" : undefined,
        }}
      >
        {(field) => (
          <field.CheckboxGroupField
            label="Interests"
            size={args.size}
            required
            items={[
              { value: "design", label: "Design" },
              { value: "engineering", label: "Engineering" },
              { value: "research", label: "Research" },
            ]}
          />
        )}
      </form.AppField>

      <form.AppField
        name="contactMethod"
        validators={{
          onChange: ({ value }) =>
            value === "" ? "Select a contact method" : undefined,
        }}
      >
        {(field) => (
          <field.RadioGroupField
            label="Contact method"
            size={args.size}
            required
            items={[
              { value: "email", label: "Email" },
              { value: "phone", label: "Phone" },
              { value: "post", label: "Post" },
            ]}
          />
        )}
      </form.AppField>

      <form.AppForm>
        <form.SubmitButton size={args.size}>Submit</form.SubmitButton>
      </form.AppForm>
    </form>
  );
};

