  selected,
  classes,
  size,
}: {
  style: NonNullable<Item["selectedStyle"]>;
  selected: boolean;
  classes: ItemClasses;
  size: FormInputSize;
}) => {
  if (style === "highlight") {
    return null;
  }

  if (style === "tick") {
    return (
      <span className={cx(classes.indicator, classes.tick)} aria-hidden="true">
        {selected ? <Icon name="check" size={checkIconSizeMap[size]} /> : null}
      </span>
