  }

  return (
    <span
      className={cx(classes.indicator, classes.checkbox)}
      aria-hidden="true"
    >
      {selected ? <Icon name="check" size={checkIconSizeMap[size]} /> : null}
    </span>
  );
};

export const ItemBody = ({
  item,
  size,
  isSelected,
  classes,
}: {
  item: Item;
  size: FormInputSize;
  isSelected: boolean;
  classes: ItemClasses;
}) => {
  const selectedStyle = item.selectedStyle ?? "highlight";
  const indent = item.indent ?? 0;

  return (
    <>
      {indent > 0 && (
        <span
          aria-hidden="true"
          style={{
            display: "inline-block",
            width: `${indent * indentUnitPx[size]}px`,
            flexShrink: 0,
          }}
        />
      )}
      {item.loading && (
        <LoadingSpinner
          size={iconSizeMap[size]}
          variant="bars"
          className={classes.spinner}
        />
      )}
      <SelectionIndicator
        style={selectedStyle}
        selected={isSelected}
        classes={classes}
        size={size}
      />
      {item.icon && (
        <Icon
          name={item.icon}
          size={iconSizeMap[size]}
          className={classes.icon}
        />
      )}
      <span className={classes.textColumn}>
        {item.text}
        {item.description !== undefined && item.description !== null && (
          <span className={classes.description}>{item.description}</span>
        )}
      </span>
      {item.subItems && item.subItems.length > 0 && (
        <Icon
          name="chevronRight"
          size={arrowIconSizeMap[size]}
          className={classes.arrow}
          aria-hidden="true"
        />
      )}
      {item.suffix && <span className={classes.suffix}>{item.suffix}</span>}
