const Controlled = ({ ...props }: NumberInputProps) => {
  const [value, setValue] = useState(props.value ?? null);
  return (
    <NumberInput {...props} value={value} onChange={(val) => setValue(val)} />
  );
};

const ClearableInput = ({
  ...props
}: Omit<NumberInputProps, "clearable" | "onChange">) => {
  const [value, setValue] = useState(props.value ?? null);
  return (
    <NumberInput
      {...props}
      value={value}
      onChange={(val) => setValue(val)}
      clearable={{ clearable: true, onClear: () => setValue(null) }}
    />
  );
};

const StyledNumberInput = ({
  clearable,
  ...props
}: Omit<
  NumberInputProps,
  "value" | "onChange" | "styledValue" | "clearable"
> & {
  clearable?: boolean;
}) => {
  const [value, setValue] = useState<number | null>(1234567890);
  return (
    <NumberInput
      {...props}
      value={value}
      onChange={(val) => setValue(val)}
      clearable={
        clearable
          ? { clearable: true, onClear: () => setValue(null) }
          : undefined
      }
      styledValue={
        value === null ? null : (
          <span style={{ color: "green", fontWeight: "bold" }}>
            {value.toLocaleString()}
