            const itemsForRow: Array<ItemOrGroup<SelectItem>> =
              row.key === "loading"
                ? []
                : [{ value: row.label, text: row.label }, ...sampleItems];
            return stateColumns.map((col) => {
              const value =
                row.key === "loading"
                  ? "loading"
                  : col.withValue
                    ? row.label
                    : "";
              const cellKey = `${row.key}-${col.key}`;
              return row.clearable ? (
                <ClearableSelect
                  key={cellKey}
                  {...args}
                  items={itemsForRow}
                  value={value}
                  variant={variant}
                  readonly={col.readonly}
                  {...row.extraProps}
                />
              ) : (
                <Controlled
                  key={cellKey}
                  {...args}
                  items={itemsForRow}
                  value={value}
                  variant={variant}
                  readonly={col.readonly}
                  {...row.extraProps}
                />
              );
            });
          })}
        </div>
      </div>
    ))}
  </div>
);

