  /** Show the input as connected to another input. To connect 2 inputs, both connectToLeftInput and connectToRightInput should be enabled on both connected inputs. subtle inputs + readonly inputs will not be connected */
  connectToRightInput?: boolean;
  /** A customized view that is shown when the input is unfocused. Can be used to present the value with extra formatting */
  styledValue?: React.ReactNode;
  /** Set to allow the input to be cleared. As the component is controlled you must clear the value manually with onClear. */
  clearable?: {
    clearable: boolean;
    onClear: () => void;
  };
  showEditIcon?: boolean;
  /** Defaults to false, set to true to allow browsers to autocomplete an input */
  autocomplete?: boolean;
  onClick?: React.MouseEventHandler<Element>;
  onKeyDown?: React.KeyboardEventHandler<Element>;
  min?: number;
  max?: number;
  step?: number | "any";
  maxLength?: number;
  minLength?: number;
  pattern?: string;
  spellcheck?: boolean;
  tabIndex?: number;
  /** Inline style applied to the outer wrapper. Useful for setting CSS variables like `--form-width`. */
  style?: React.CSSProperties;
} & SharedInputProps<
  HTMLInputElement,
  string | null | undefined,
  (value: string, event: React.ChangeEvent<HTMLInputElement>) => void
> &
  React.AriaAttributes;

type BaseInputSlots = ReturnType<typeof baseInputRecipe>;
type PrefixOrSuffix = (
  | { iconName: IconName; onClick?: () => void; disabled?: boolean }
  | { text: string; onClick?: () => void; disabled?: boolean }
  | { content: React.ReactNode }
) & { variant?: "default" | "subtle" };

function isIconAdornment(
  val: unknown,
): val is { iconName: IconName; onClick?: () => void } {
  return val != null && typeof val === "object" && "iconName" in val;
}

function isTextAdornment(
  val: unknown,
): val is { text: string; onClick?: () => void } {
  return val != null && typeof val === "object" && "text" in val;
}

const iconSizeMap: Record<FormInputSize, FormInputSize> = {
  xxs: "xs",
  xs: "xs",
  sm: "sm",
  md: "md",
  lg: "md",
};

const loadingSizeMap: Record<FormInputSize, FormInputSize> = {
  xxs: "xs",
  xs: "xs",
  sm: "sm",
  md: "sm",
  lg: "md",
};

function renderAdornment(
  type: "prefix" | "suffix",
  adornment: PrefixOrSuffix,
  size: FormInputSize,
  classes: BaseInputSlots,
): React.ReactNode {
  const content = isIconAdornment(adornment) ? (
    <Icon name={adornment.iconName} size={iconSizeMap[size]} />
  ) : isTextAdornment(adornment) ? (
    adornment.text
  ) : (
    adornment.content
  );
  const dataVariant = adornment.variant === "subtle" ? "subtle" : undefined;
  if (!("content" in adornment) && adornment.onClick) {
    return (
      <button
        type="button"
        onClick={adornment.onClick}
        disabled={adornment.disabled}
        data-part="adornment-button"
        data-variant={dataVariant}
        className={cx(
          classes[type],
          classes.adornment,
          classes.adornmentButton,
          adornment.disabled && classes.disabledButton,
        )}
      >
        {content}
      </button>
    );
  }
  return (
    <span
      className={cx(classes[type], classes.adornment, classes.adornmentText)}
      data-part="adornment-text"
      data-variant={dataVariant}
    >
      {content}
    </span>
  );
}

export const BaseInput = ({
  type = "text",
  inputMode,
  placeholder,
  readonly,
  loading,
  variant = "default",
  align = "left",
  width = "fullWidth",
  prefix,
  suffix,
  connectToLeftInput,
  connectToRightInput,
  styledValue,
  clearable,
  showEditIcon,
  onClick,
  onKeyDown,
  min,
  max,
  step,
  maxLength,
  minLength,
  pattern,
  spellcheck,
  autocomplete = false,
  className,
  style,
  name,
  value,
  onChange,
  onFocus,
  onBlur,
  size = "md",
  testId,
  htmlForId,
  ref,
  inputRef,
  disabled,
  required,
  invalid,
  autoFocus,
  ...ariaProps
}: BaseInputProps) => {
  const [focused, setFocused] = useState(false);
  const internalRef = useRef<HTMLInputElement>(null);
  const mergedInputRef = useMergeRefs([
    internalRef,
    ...(inputRef ? [inputRef] : []),
  ]);
  const fieldIdFromContext = useFieldId();
  const inputId = htmlForId ?? fieldIdFromContext ?? undefined;

  const hasBrowserControls = type === "number";
  const noAutocomplete = !!clearable || !autocomplete;
  const showClear = !!(clearable && !disabled);
  const hasIcons = !!loading || showClear;
  const connectsLeft = connectToLeftInput && variant === "default";
  const connectsRight = connectToRightInput && variant === "default";
  const subtlePrefix = variant === "default" && prefix?.variant === "subtle";

  const classes = baseInputRecipe({
    variant,
    size,
    align,
    width,
    invalid: !!invalid,
    disabled: !!disabled,
    loading: !!loading,
    hasBrowserControls,
    hasIcons,
    editAndClear: showClear && showEditIcon,
    connectsLeft,
    connectsRight,
    subtlePrefix,
    willClear:
      showClear &&
      clearable.clearable &&
      (value === null || value === undefined),
  });

  if (readonly) {
    return (
      <span
        ref={ref}
        className={cx(classes.readonly, className)}
        data-testid={testId}
        {...ariaProps}
      >
        {styledValue ?? value ?? ""}
      </span>
    );
  }

  const input = (
    <input
      id={inputId}
      ref={mergedInputRef}
      type={type}
      inputMode={inputMode}
      name={name}
      value={value ?? ""}
      placeholder={placeholder}
      disabled={disabled}
      required={required}
      aria-invalid={invalid ?? undefined}
      onChange={(event) => {
        onChange(event.target.value, event);
      }}
      onFocus={(event) => {
        setFocused(true);
        onFocus?.(event);
      }}
      onBlur={(event) => {
        setFocused(false);
        onBlur?.(event);
      }}
      onKeyDown={onKeyDown}
      min={min}
      max={max}
      step={step}
      maxLength={maxLength}
      minLength={minLength}
      pattern={pattern}
      spellCheck={spellcheck}
      {...(noAutocomplete ? preventAutocompleteProps : {})}
      data-testid={testId}
      className={cx(
        classes.input,
        styledValue && !focused ? classes.hiddenInput : undefined,
      )}
      {...resolveAutoFocusProps(autoFocus)}
      {...ariaProps}
    />
  );

  return (
    <div
      ref={ref as React.Ref<HTMLDivElement>}
      className={cx(classes.wrapper, className)}
      style={style}
    >
      {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions -- click-to-focus container delegates to inner <input> */}
      <div
        className={classes.root}
        onClick={(event) => {
          if (!disabled) {
            internalRef.current?.focus();
            onClick?.(event);
          }
        }}
      >
        {prefix != null && renderAdornment("prefix", prefix, size, classes)}
        {connectToLeftInput && variant === "default" && (
          <InputConnector
            className={cx(
              classes.connector,
              classes.connectLeft,
              prefix && classes.connectAdornment,
            )}
            data-part="connector"
          />
        )}

        <div className={classes.inputWrapper}>
          {input}
          {styledValue && !focused && (
            <div className={classes.styledValueOverlay}>{styledValue}</div>
          )}
          {showClear && (
            <button
              type="button"
              data-part="clear"
              onMouseDown={(event) => {
                // prevents focus from changing/being removed from the input which can lead to UI stutter
                // if selectedDisplay is set
                event.preventDefault();
                event.stopPropagation();
              }}
              onClick={(event) => {
                event.preventDefault();
                event.stopPropagation();
                clearable.onClear();
                internalRef.current?.focus();
              }}
              className={cx(
                classes.clear,
                (!clearable.clearable || !value) && classes.hideClear,
              )}
              aria-label="Clear input"
            >
              <Icon
                name="close"
                size={iconSizeMap[size]}
                className={classes.clearIcon}
              />
            </button>
          )}
          {!disabled && showEditIcon && (
            <span className={classes.editIcon} data-part="edit">
              <Icon name="pencil" size={loadingSizeMap[size]} />
            </span>
          )}
        </div>

        {loading && (
          <span className={classes.loading} data-part="loading">
            <LoadingSpinner size={loadingSizeMap[size]} variant="bars" />
          </span>
        )}

        {suffix != null && renderAdornment("suffix", suffix, size, classes)}
        {connectToRightInput && variant === "default" && (
          <InputConnector
            className={cx(
              classes.connector,
              classes.connectRight,
              suffix && classes.connectAdornment,
            )}
            data-part="connector"
          />
        )}
      </div>
    </div>
  );
};

export const InputConnector = ({
  className,
  "data-part": dataPart,
}: {
  className?: string;
  "data-part"?: string;
}) => {
  return (
    <svg
      viewBox="0 0 20 62"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      data-part={dataPart}
    >
      <path
        d="M 0 9 A 10 9 0 0 0 20 9 L 20 53 A 10 9 0 0 0 0 53 Z"
        fill="inherit"
      />
      <path
        d="M 0 9 A 10 9 0 0 0 20 9"
        stroke="currentColor"
        strokeWidth="inherit"
        vectorEffect="non-scaling-stroke"
        fill="none"
      />
      <path
        d="M 0 53 A 10 9 0 0 1 20 53"
        stroke="currentColor"
        strokeWidth="inherit"
        vectorEffect="non-scaling-stroke"
        fill="none"
      />
    </svg>
  );
};

