  const tokenPath = `colors.neutral.${step}` as Token;
  const bgColor = token(tokenPath);

  return (
    <div
      className={swatchStyles}
      style={{
        backgroundColor: bgColor,
        boxShadow: "inset 0 0 0 1px rgba(0,0,0,0.08)",
      }}
    >
